fn bitwise_or(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    // Use zip to pair elements from both vectors, apply bitwise OR, and collect
    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| x | y)
        .collect()
}